import { performance } from "node:perf_hooks";

function bench(name: string, runs: number, fn: () => unknown | Promise<unknown>) {
	const times: number[] = [];
	for (let i = 0; i < runs; i++) {
		const t0 = performance.now();
		fn();
		times.push(performance.now() - t0);
	}
	times.sort((a, b) => a - b);
	const avg = times.reduce((a, b) => a + b, 0) / times.length;
	console.log(
		`${name.padEnd(48)} n=${runs} avg=${avg.toFixed(2)}ms p50=${times[Math.floor(runs * 0.5)].toFixed(2)} p95=${times[Math.floor(runs * 0.95)].toFixed(2)}`,
	);
	return avg;
}

