const fakeClient = new Proxy(
	{},
	{
		get(_target, prop) {
			return () => Promise.resolve({});
		},
	},
) as never;

function makeUniqueName(seed: string) {
	// Ensure each iteration's schema objects are fresh, like real requests.
	return `${seed}`;
}

const options = () => ({
	createClient: () => fakeClient as never,
});

