/* Scratch benchmark: does the SDK eagerly convert compactJsonSchema-wrapped schemas? Deleted before commit. */
import { performance } from "node:perf_hooks";
import { z } from "zod";
import { McpServer } from "@modelcontextprotocol/server";
import { compactJsonSchema } from "./packages/core/src/utils/compact-json-schema.js";
import { hevyToolDefinitions } from "./packages/core/src/tools/register.js";

function bench(name: string, runs: number, fn: () => unknown) {
	const times: number[] = [];
	for (let i = 0; i < runs; i++) {
		const t0 = performance.now();
		fn();
		times.push(performance.now() - t0);
	}
	times.sort((a, b) => a - b);
	const avg = times.reduce((a, b) => a + b, 0) / runs;
	console.log(
		`${name.padEnd(56)} avg=${avg.toFixed(2)}ms  p50=${times[Math.floor(runs * 0.5)].toFixed(2)}ms  p95=${times[Math.floor(runs * 0.95)].toFixed(2)}ms`,
	);
}

const makeServer = () =>
	new McpServer(
		{ name: "hevy-mcp", version: "0.1.0" },
		{ capabilities: { logging: {} } },
	);

const reg = (schema: unknown) => {
	const server = makeServer();
	for (const def of hevyToolDefinitions) {
		(server.registerTool as (n: string, c: object, h: () => unknown) => void)(
			def.name,
			{ description: def.description, inputSchema: schema as never },
			() => ({ content: [] }),
		);
	}
	return server;
};

const plainSchema = () => {
	const schemas = hevyToolDefinitions.map((d) => z.strictObject(d.inputSchema));
	reg(schemas);
};
const compactSchema = () => {
	const schemas = hevyToolDefinitions.map((d) =>
		compactJsonSchema(z.strictObject(d.inputSchema)),
	);
	reg(schemas);
};
plainSchema();
compactSchema();
bench("registerTool x22  plain strictObject schemas", 40, plainSchema);
bench("registerTool x22  compactJsonSchema-wrapped", 40, compactSchema);

