/* Scratch benchmark: attribute handler-shell vs schema config; test config caching. Deleted before commit. */
import { performance } from "node:perf_hooks";
import { z } from "zod";
import { McpServer } from "@modelcontextprotocol/server";
import { compactJsonSchema } from "./packages/core/src/utils/compact-json-schema.js";
import { createTypedToolHandler } from "./packages/core/src/utils/tool-helpers.js";
import { hevyToolDefinitions } from "./packages/core/src/tools/register.js";
import { registerToolDefinition } from "./packages/core/src/tools/define-tool.js";
import type { ToolRuntime } from "./packages/core/src/tools/tool-runtime.js";
import { respond, responseContract } from "./packages/core/src/utils/response-contracts.js";

function bench(name: string, runs: number, fn: () => unknown) {
	const times: number[] = [];
	for (let i = 0; i < runs; i++) {
		const t0 = performance.now();
		fn();
		times.push(performance.now() - t0);
	}
	times.sort((a, b) => a - b);
	const avg = times.reduce((a, b) => a + b, 0) / runs;
	console.log(
		`${name.padEnd(58)} avg=${avg.toFixed(2)}ms  p50=${times[Math.floor(runs * 0.5)].toFixed(2)}ms  p95=${times[Math.floor(runs * 0.95)].toFixed(2)}ms`,
	);
}

const makeServer = () =>
	new McpServer(
		{ name: "hevy-mcp", version: "0.1.0" },
		{ capabilities: { logging: {} } },
	);

const fakeRuntime = {
	createHandler: (direct: never, name: string) => (_args: never) => direct,
	forExecution: (x: never) => x,
} as unknown as ToolRuntime;

// --- handler shell only (createTypedToolHandler + respond-wrapped execute) ---
const shellOnly = () => {
	let n = 0;
	for (const def of hevyToolDefinitions) {
		createTypedToolHandler(def.inputSchema, async (args) =>
			respond(
				(responseContract as unknown as never) as never,
				await (def.execute as never)(null, args),
			),
		);
		n += 1;
	}
	return n;
};
void shellOnly;
bench("handler shell only (22x)", 100, () => {
	void shellOnly();
});

// --- schema-config only ---
const buildConfigs = () => {
	const configs: unknown[] = [];
	for (const def of hevyToolDefinitions) {
		const inputSchema = compactJsonSchema(z.strictObject(def.inputSchema));
		const config: Record<string, unknown> = {
			description: def.description,
			inputSchema,
			annotations: def.annotations,
		};
		if (def.outputSchema) config.outputSchema = compactJsonSchema(z.object(def.outputSchema));
		configs.push(config);
	}
	return configs;
};
buildConfigs();
bench("schema-config build (22x, fresh)", 100, buildConfigs);

// --- CONTROL: full registerToolDefinition today ---
const registerAll = () => {
	const server = makeServer();
	for (const def of hevyToolDefinitions) {
		registerToolDefinition(server as never, fakeRuntime, def as never);
	}
	return server;
};
registerAll();
bench("registerToolDefinition x22 (today)", 60, registerAll);

// --- PROPOSED: cached configs, fresh server + fresh handler shell ---
const configCache = new Map<unknown, unknown>();
const getConfig = (def: unknown) => {
	let c = configCache.get(def);
	if (!c) {
		const d = def as (typeof hevyToolDefinitions)[number];
		const config: Record<string, unknown> = {
			description: d.description,
			inputSchema: compactJsonSchema(z.strictObject(d.inputSchema)),
			annotations: d.annotations,
		};
		if (d.outputSchema) config.outputSchema = compactJsonSchema(z.object(d.outputSchema));
		c = config;
		configCache.set(def, c);
	}
	return c;
};

const registerAllCached = () => {
	const server = makeServer();
	for (const def of hevyToolDefinitions) {
		const config = getConfig(def) as { description: string; inputSchema: unknown; annotations: unknown };
		const direct = createTypedToolHandler(def.inputSchema, async () =>
			respond((responseContract as never) as never, await (def.execute as never)(null, {} as never)),
		);
		server.registerTool(
			def.name,
			config as never,
			((_args: unknown, _ctx?: unknown) => direct(_args)) as never,
		);
	}
	return server;
};
getConfig(hevyToolDefinitions[0]); // warm cache
registerAllCached();
bench("register with CACHED configs x22", 60, registerAllCached);

