function bench(name: string, runs: number, fn: () => unknown) {
	const times: number[] = [];
	for (let i = 0; i < runs; i++) {
		const t0 = performance.now();
		fn();
		times.push(performance.now() - t0);
	}
	times.sort((a, b) => a - b);
	const avg = times.reduce((a, b) => a + b, 0) / runs;
	console.log(
		`${name.padEnd(56)} avg=${avg.toFixed(3)}ms  p50=${times[Math.floor(runs * 0.5)].toFixed(3)}ms  p95=${times[Math.floor(runs * 0.95)].toFixed(3)}ms`,
	);
}

