/* Scratch verification of the fix. Deleted before commit. */
import { performance } from "node:perf_hooks";
import { createHevyMcpServer, preloadHevyToolSchemas } from "@hevy-mcp/core";

const fakeClient = new Proxy({}, { get: () => () => Promise.resolve({}) }) as never;
const options = () => ({ createClient: () => fakeClient as never });

function bench(name: string, runs: number, fn: () => unknown): number {
	const times: number[] = [];
	for (let i = 0; i < runs; i++) {
		const t0 = performance.now();
		fn();
		times.push(performance.now() - t0);
	}
	times.sort((a, b) => a - b);
	const avg = times.reduce((a, b) => a + b, 0) / runs;
	console.log(`${name.padEnd(52)} avg=${avg.toFixed(2)}ms  p50=${times[Math.floor(runs * 0.5)].toFixed(2)}ms  p95=${times[Math.floor(runs * 0.95)].toFixed(2)}ms`);
	return avg;
}

// warm the JIT
for (let i = 0; i < 5; i++) createHevyMcpServer(options());

// simulate steady-state requests in a warm isolate (cache is now full)
bench("createHevyMcpServer warm-isolate (fixed)", 60, () => {
	createHevyMcpServer(options());
});

// simulate what happens WITHOUT module-scope preload on a fresh isolate:
// reset is not exposed; instead show the preload endpoint warms without building a server.
const t0 = performance.now();
preloadHevyToolSchemas();
console.log(`preloadHevyToolSchemas() cost (cold isolate, once): ${(performance.now() - t0).toFixed(2)}ms`);
EOF
