it("shares memoized tool schemas across independently built servers", async () => {
	preloadHevyToolSchemas();
	preloadHevyToolSchemas();
	const catalog: ExerciseTemplateCatalog = {
		get: () => Promise.resolve([]),
		reset: () => {},
	};
	const rebuildServer = () => {
		const rebuilt = new McpServer({ name: "tool-list-rebuilt", version: "1.0.0" });
		registerHevyTools(
			rebuilt,
			createToolRuntime({ client: null, catalog }),
		);
		return rebuilt;
	};
	const secondServer = rebuildServer();

	const firstClient = new Client({ name: "tool-list-first", version: "1.0.0" });
	const secondClient = new Client({ name: "tool-list-second", version: "1.0.0" });
	const [, firstServerTransport] = InMemoryTransport.createLinkedPair();
	const secondServerTransport = new InMemoryTransport();
	try {
		await Promise.all([
			server.connect(firstServerTransport),
			firstClient.connect(firstServerTransport),
			secondServer.connect(secondServerTransport),
			secondClient.connect(secondServerTransport),
		]);
		const [first, second] = await Promise.all([
			firstClient.listTools(),
			secondClient.listTools(),
		]);

		expect(second.tools).toEqual(first.tools);
		expect(second.tools).toHaveLength(EXPECTED_TOOL_NAMES.length);

		// The memoized path must also hold through yet another rebuild.
		const thirdServer = rebuildServer();
		const thirdClient = new Client({ name: "tool-list-third", version: "1.0.0" });
		const thirdServerTransport = new InMemoryTransport();
		await Promise.all([
			thirdServer.connect(thirdServerTransport),
			thirdClient.connect(thirdServerTransport),
		]);
		try {
			const third = await thirdClient.listTools();
			expect(third.tools).toEqual(first.tools);
		} finally {
			await Promise.all([thirdClient.close(), thirdServer.close()]);
		}
	} finally {
		await Promise.all([
			firstClient.close(),
			secondClient.close(),
			secondServer.close(),
		]);
	}
});

